                  style={{
                    position: 'absolute',
                    top: 6,
                    right: 6,
                    height: 18,
                    minWidth: 18,
                    paddingLeft: 6,
                    paddingRight: 6,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '0.65rem',
                    lineHeight: '18px',
                    zIndex: 2,
                  }}
                >
                  {conversation.unreadCount > 99 ? '99+' : conversation.unreadCount}
